import re
import subprocess
from collections import defaultdict
from io import BytesIO
from pathlib import Path

from reportlab.pdfgen import canvas
from pypdf import PdfReader, PdfWriter

EMAIL_RE = re.compile(r"[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}", re.I)
DOI_RE = re.compile(r"10\.\d{4,9}/\S+", re.I)
ARXIV_RE = re.compile(r"arxiv:\d{4}\.\d{4,5}(v\d+)?", re.I)
CLASS_RE = re.compile(r"^\[[A-Za-z]+\.[A-Za-z]+\]$")
YEAR_RE = re.compile(r"^20\d{2}$")
DAY_RE = re.compile(r"^\d{1,2}$")

MONTHS = {"jan","feb","mar","apr","may","jun","jul","aug","sep","sept","oct","nov","dec"}

AFFIL_KW = [
    "university","institute","laboratory","laboratories","department","school",
    "college","research","center","centre","inc.","ltd","corp","corporation",
    "company","academy","faculty","graduate","campus"
]

VENUE_KW = [
    "interspeech","conference","workshop","symposium","proceedings",
    "transactions","journal","icml","neurips","cvpr","acl","emnlp",
    "naacl","eccv","iccv","icassp","aaai","ijcai"
]

STOP_TOKENS = {"and","the","of","for","in","on","with","to"}


def pdftotext_bbox(pdf_path: str):
    html = subprocess.check_output(["pdftotext", "-bbox", pdf_path, "-"]).decode("utf-8", "ignore")
    pages = re.findall(r"<page[^>]*?>.*?</page>", html, re.S)
    out_pages = []
    for page_html in pages:
        m = re.search(r"<page[^>]*?width=\"([\d.]+)\" height=\"([\d.]+)\"", page_html)
        width = float(m.group(1)) if m else None
        height = float(m.group(2)) if m else None
        words = []
        for m in re.finditer(r"<word xMin=\"([\d.]+)\" yMin=\"([\d.]+)\" xMax=\"([\d.]+)\" yMax=\"([\d.]+)\">(.*?)</word>", page_html):
            x0,y0,x1,y1,text = m.groups()
            text = re.sub(r"\s+", " ", text)
            words.append({
                "x0": float(x0), "y0": float(y0),
                "x1": float(x1), "y1": float(y1),
                "text": text,
            })
        out_pages.append({"width": width, "height": height, "words": words})
    return out_pages


def group_lines(words, y_tol=2.0):
    lines = []
    for w in sorted(words, key=lambda w: (w["y0"], w["x0"])):
        y = w["y0"]
        placed = False
        for line in lines:
            if abs(line["y"] - y) < y_tol:
                line["words"].append(w)
                # keep y as average
                line["y"] = (line["y"] * (len(line["words"]) - 1) + y) / len(line["words"])
                placed = True
                break
        if not placed:
            lines.append({"y": y, "words": [w]})

    out = []
    for line in lines:
        ws = sorted(line["words"], key=lambda w: w["x0"])
        text = " ".join(w["text"] for w in ws)
        x0 = min(w["x0"] for w in ws)
        x1 = max(w["x1"] for w in ws)
        y0 = min(w["y0"] for w in ws)
        y1 = max(w["y1"] for w in ws)
        out.append({"x0": x0, "x1": x1, "y0": y0, "y1": y1, "text": text, "words": ws})
    return sorted(out, key=lambda l: l["y0"])


def build_author_tokens(reader: PdfReader):
    meta = reader.metadata or {}
    raw = meta.get("/Author") or ""
    if not raw:
        return set()
    parts = re.split(r"[;,]", raw)
    tokens = set()
    for part in parts:
        for tok in re.findall(r"[A-Za-z][A-Za-z\-']+", part):
            t = tok.strip().lower()
            if len(t) < 3 or t in STOP_TOKENS:
                continue
            tokens.add(t)
    return tokens


def contains_author_token(text, tokens):
    if not tokens:
        return False
    for tok in tokens:
        if re.search(rf"\b{re.escape(tok)}\b", text, re.I):
            return True
    return False


def is_author_like_line(text):
    # Heuristic: multiple capitalized words and punctuation typical for author lists
    caps = re.findall(r"\b[A-Z][a-zA-Z\-']+\b", text)
    if len(caps) < 3:
        return False
    if "," in text or "*" in text or "†" in text or "·" in text:
        return True
    if re.search(r"\d", text):
        return True
    return False


def is_affiliation_line(text):
    t = text.lower()
    return any(kw in t for kw in AFFIL_KW)


def is_venue_line(text):
    t = text.lower()
    return any(kw in t for kw in VENUE_KW)


def redact_boxes_for_page(page, author_tokens):
    words = page["words"]
    width = page["width"]
    height = page["height"]
    lines = group_lines(words)
    boxes = []

    for line in lines:
        text = line["text"].strip()
        t_lower = text.lower()
        y0, y1 = line["y0"], line["y1"]
        header = y0 < 80
        footer = y1 > (height - 80)

        redact = False
        if EMAIL_RE.search(text):
            redact = True
        if "correspondence" in t_lower or "contact" in t_lower:
            redact = True
        if contains_author_token(text, author_tokens) and y0 < 250:
            redact = True
        if is_author_like_line(text) and y0 < 250:
            redact = True
        if is_affiliation_line(text) and y0 < 300:
            redact = True
        if is_venue_line(text) and (header or footer or y0 < 120):
            redact = True
        if DOI_RE.search(text) and (header or footer or y0 < 120):
            redact = True

        if redact:
            boxes.append((line["x0"], line["y0"], line["x1"], line["y1"]))

    # arXiv / classification stamp detection in margins
    stamp_words = []
    for w in words:
        tx = w["text"].strip()
        if w["x0"] > 60:
            continue
        if ARXIV_RE.search(tx) or CLASS_RE.match(tx) or YEAR_RE.match(tx) or (tx.lower() in MONTHS) or DAY_RE.match(tx):
            stamp_words.append(w)
    if stamp_words:
        x0 = min(w["x0"] for w in stamp_words)
        x1 = max(w["x1"] for w in stamp_words)
        y0 = min(w["y0"] for w in stamp_words)
        y1 = max(w["y1"] for w in stamp_words)
        # widen a bit to cover vertical stamp
        boxes.append((max(0, x0 - 5), y0 - 2, min(width, x1 + 5), y1 + 2))

    return boxes


def merge_overlays(reader, redact_map):
    writer = PdfWriter()
    for i, page in enumerate(reader.pages):
        page_width = float(page.mediabox.width)
        page_height = float(page.mediabox.height)
        rects = redact_map.get(i, [])

        if rects:
            buf = BytesIO()
            can = canvas.Canvas(buf, pagesize=(page_width, page_height))
            can.setFillColorRGB(0, 0, 0)
            for (x0, y0, x1, y1) in rects:
                # convert top-left origin to bottom-left origin
                rx = max(0, x0 - 1)
                ry = page_height - y1 - 1
                rw = max(0, (x1 - x0) + 2)
                rh = max(0, (y1 - y0) + 2)
                can.rect(rx, ry, rw, rh, stroke=0, fill=1)
            can.save()
            buf.seek(0)
            overlay = PdfReader(buf).pages[0]
            page.merge_page(overlay)

        writer.add_page(page)

    # scrub metadata
    writer.add_metadata({})
    try:
        writer.xmp_metadata = None
    except Exception:
        pass
    return writer


def redact_pdf(input_pdf: str, output_pdf: str):
    reader = PdfReader(input_pdf)
    author_tokens = build_author_tokens(reader)
    pages_bbox = pdftotext_bbox(input_pdf)

    redact_map = defaultdict(list)
    for idx, page in enumerate(pages_bbox):
        rects = redact_boxes_for_page(page, author_tokens)
        if rects:
            redact_map[idx].extend(rects)

    writer = merge_overlays(reader, redact_map)

    output_path = Path(output_pdf)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    with open(output_path, "wb") as f:
        writer.write(f)


def main():
    in_files = ["/root/paper1.pdf", "/root/paper2.pdf", "/root/paper3.pdf"]
    out_files = ["/root/redacted/paper1.pdf", "/root/redacted/paper2.pdf", "/root/redacted/paper3.pdf"]
    for inp, out in zip(in_files, out_files):
        redact_pdf(inp, out)

if __name__ == "__main__":
    main()
