def render_pages_to_png(pdf_path: str, out_dir: Path, dpi: int):
    out_dir.mkdir(parents=True, exist_ok=True)
    prefix = str(out_dir / "page")
    subprocess.check_call(["pdftocairo", "-png", "-r", str(dpi), pdf_path, prefix])
    # pdftocairo outputs page-1.png, page-2.png, ...
    images = sorted(out_dir.glob("page-*.png"), key=lambda p: int(p.stem.split("-")[-1]))
    return images


def apply_redactions_to_images(image_paths, redactions, dpi):
    scale = dpi / 72.0
    for idx, img_path in enumerate(image_paths):
        rects = redactions.get(idx, [])
        if not rects:
            continue
        img = Image.open(img_path)
        draw = ImageDraw.Draw(img)
        for (x0, y0, x1, y1) in rects:
            rx0 = max(0, int((x0 - 1) * scale))
            ry0 = max(0, int((y0 - 1) * scale))
            rx1 = min(img.width, int((x1 + 1) * scale))
            ry1 = min(img.height, int((y1 + 1) * scale))
            draw.rectangle([rx0, ry0, rx1, ry1], fill="black")
